var WsGrandEd string

var EmpRecVar EmpRec

var inputDone bool
var firstRecord bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func storeDecimal(v decimal.Decimal, intDigits int32, scale int32, doRound bool) decimal.Decimal {
	var r decimal.Decimal
	if doRound {
		r = v.Round(scale)
	} else {
		r = v.Truncate(scale)
	}
	// keep low-order digits that fit (overflow truncation)
	// total digits = intDigits + scale ; for scale 0, total = intDigits
	if intDigits+scale <= 0 {
		return r
	}
	// compute modulus = 10^(intDigits+scale)
	// r *10^scale is integer; do modulo
	shifted := r.Shift(scale) // r *10^scale
	// For positive numbers simple modulo; handle negative by preserving sign
	sign := shifted.Sign()
	if sign < 0 {
		shifted = shifted.Abs()
	}
	modStr := "1"
	for i := int32(0); i < intDigits+scale; i++ {
		modStr += "0"
	}
	mod, _ := decimal.NewFromString(modStr)
	// low-order digits
	// shifted is integral after shift, use Mod
	low := shifted.Mod(mod)
	if sign < 0 {
		low = low.Neg()
	}
	return low.Shift(-scale)
}

func storeInt(v int64, digits int) int64 {
	if digits <= 0 {
		return v
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, preserve sign
	if v < 0 {
		return -((-v) % mod)
	}
	return v % mod
}

func formatNumericEdited(v decimal.Decimal, picture string) string {
	// split picture on '.'
	var intPic, decPic string
	if idx := strings.Index(picture, "."); idx >= 0 {
		intPic = picture[:idx]
		decPic = picture[idx+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	decDigits := len(decPic) // number of 9/Z after dot
	// count integer digit positions
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	// round to decDigits for display (MOVE to edited rounds)
	rv := v.Round(int32(decDigits))
	if rv.Sign() < 0 {
		rv = rv.Abs()
	}
	// split integer and fractional
	// fractional part
	var fracStr string
	if decDigits > 0 {
		// Shift and get fractional
		// Use string formatting to get exactly decDigits
		// We have rv rounded
		s := rv.StringFixed(int32(decDigits)) // includes decimal point
		parts := strings.SplitN(s, ".", 2)
		if len(parts) == 2 {
			fracStr = parts[1]
			if len(fracStr) < decDigits {
				fracStr = fracStr + strings.Repeat("0", decDigits-len(fracStr))
			} else if len(fracStr) > decDigits {
				fracStr = fracStr[:decDigits]
			}
		} else {
			fracStr = strings.Repeat("0", decDigits)
		}
		rv = partsToDecimal(parts[0])
	} else {
		rv = rv.Truncate(0)
	}
	// integer part value
	intVal := rv.IntPart() // fits within int64 for these sizes
	// overflow: keep low-order intDigits digits
	if intDigits > 0 {
		mod := int64(1)
		for i := 0; i < intDigits; i++ {
			mod *= 10
		}
		intVal = intVal % mod
		if intVal < 0 {
			intVal = -intVal
		}
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intVal)
	// Build integer picture output with Z suppression
	// Map digit positions to picture characters
	// We need to walk intPic left to right, filling digits
	// intPic contains commas and digit placeholders
	outInt := make([]rune, len(intPic))
	digitIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			outInt[i] = rune(intStr[digitIdx])
			digitIdx++
		} else {
			outInt[i] = ch // comma
		}
	}
	// Z suppression: leading zeros become spaces
	// Find last Z position; zeros beyond that are not suppressed (9s)
	// Leading zone is from start until last Z inclusive; if digit is '0' and not yet encountered non-zero, replace with space
	// Commas in suppressed zone become spaces
	suppressing := true
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			if suppressing {
				if outInt[i] == '0' {
					if ch == 'Z' {
						outInt[i] = ' '
					} else {
						// '9' in suppressing zone but it's the mandatory digit
						// If it's zero and still suppressing, it should be '0' not space
						// But if all leading are zeros, the 9 should be '0'
						// So stop suppressing and keep 0
						suppressing = false
					}
				} else {
					suppressing = false
				}
			}
		} else if ch == ',' {
			if suppressing {
				// check if any non-space digit remains to the right beyond suppression?
				// Actually commas become spaces while still suppressing
				outInt[i] = ' '
			}
		}
		// If we have become non-suppressing, commas stay as commas
		if !suppressing {
			// need to ensure commas that were previously set to space stay space? no, they were before suppression ended
			// nothing
		}
		_ = i
	}
	// Special: if intPic suppressing would make all spaces, the mandatory 9 ensures at least one zero
	result := string(outInt)
	if decDigits > 0 {
		result = result + "." + fracStr
	}
	return result
}

func partsToDecimal(s string) decimal.Decimal {
	if s == "" {
		return decimal.Zero
	}
	d, _ := decimal.NewFromString(s)
	return d
}

func formatPIC9(v int64, digits int) string {
	// zero-padded
	if v < 0 {
		v = -v
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v = v % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func readEmpFile(scanner *bufio.Scanner) bool {
	if !scanner.Scan() {
		WsEofFlag = "Y"
		return false
	}
	line := scanner.Text()
	// pad to 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	}
	if len(line) > 17 {
		line = line[:17]
	}
	EmpRecVar.ErId = line[0:5]
	EmpRecVar.ErDept = line[5:8]
	hoursRaw := line[8:12]
	rateRaw := line[12:17]
	// parse numeric: digits only
	EmpRecVar.ErHours = parseImpliedDecimal(hoursRaw, 1)
	EmpRecVar.ErRate = parseImpliedDecimal(rateRaw, 2)
	return true
}

func parseImpliedDecimal(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// keep only digits and sign
	neg := false
	digits := ""
	for _, c := range s {
		if c == '-' {
			neg = true
		} else if c >= '0' && c <= '9' {
			digits += string(c)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	n, _ := decimal.NewFromString(digits)
	if neg {
		n = n.Neg()
	}
	return n.Shift(-scale)
}

var scanner *bufio.Scanner

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.Zero
	WsOtHours = decimal.Zero
	WsGross = decimal.Zero
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
	WsGrandTotal = decimal.Zero
	WsGrandCount = 0

	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner = bufio.NewScanner(f)
	// preserve trailing spaces: bufio.Scanner strips newline but keeps other spaces? It returns line without newline, trailing spaces are kept? Scanner splits on newline, keeps content. So okay.
	// Need to allow long lines
	// default 64k ok

	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT EMP-FILE
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		DEPT_BREAK_PARA()
	}
	// CLOSE
	GRAND_PARA()
}

func READ_PARA() {
	if !readEmpFile(scanner) {
		// AT END already set
	}
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	// EVALUATE
	forty := decimal.NewFromInt(40)
	if EmpRecVar.ErHours.GreaterThan(forty) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1, false)
		WsOtHours = storeDecimal(EmpRecVar.ErHours.Sub(forty), 3, 1, false)
	} else {
		WsRegHours = storeDecimal(EmpRecVar.ErHours, 3, 1, false)
		WsOtHours = storeDecimal(decimal.Zero, 3, 1, false)
	}
	// COMPUTE WS-GROSS ROUNDED
	onePointFive := decimal.NewFromFloat(1.5)
	calc := WsRegHours.Mul(EmpRecVar.ErRate).Add(WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive))
	WsGross = storeDecimal(calc, 7, 2, true)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	// store truncated? ADD to PIC 9(9)V99 keeps low-order? But accumulate; we can store truncated to size
	WsDeptTotal = storeDecimal(WsDeptTotal, 9, 2, false)
	WsDeptCount = storeInt(WsDeptCount+1, 3)

	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandTotal = storeDecimal(WsGrandTotal, 11, 2, false)
	WsGrandCount = storeInt(WsGrandCount+1, 5)

	WsHoursEd = formatNumericEdited(WsRegHours.Add(WsOtHours), "ZZ9.9")
	// Actually source was ER-HOURS moved to WS-HOURS-ED, but we have original
	WsHoursEd = formatNumericEdited(EmpRecVar.ErHours, "ZZ9.9")
	WsRateEd = formatNumericEdited(EmpRecVar.ErRate, "ZZ9.99")
	WsGrossEd = formatNumericEdited(WsGross, "Z,ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatNumericEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	// WS-DEPT-COUNT is PIC 9(3) zero-padded
	cntStr := formatPIC9(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, cntStr, WsDeptEd)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func GRAND_PARA() {
	WsGrandEd = formatNumericEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	cntStr := formatPIC9(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", cntStr, WsGrandEd)
}
